/* ============================================================
   TEST PAGE 3 — A PORTRAIT OF THE PERFUMERS (2026-11-06, in place of "Top,
   middle and base").

   The owner: "replace TP3 with another iterations of the perfumers page,
   which should look like image 3. Make it as functional and as
   representative as possible." Image 3: a poster, "Portrait ethnique du
   Canada" — on charcoal, the countries of origin along the top, each a bar
   as wide as its people and named upright over it, red at the left through
   orange and gold to white at the right; from every bar fine threads
   falling in curves to the provinces, set about the poster each with a row
   of small squares — its people from each country — and its name under it;
   a legend along the foot.

   Here, the other way up — the owner, seeing it: "reverse it: i want the
   bottom parts to be the perfumers, and then that leads into houses and
   perfumes at the top": the PERFUMERS along the foot, each a bar as wide as
   its perfumes, A to Z, red to white, its name upright under it; a THREAD
   FOR EVERY PERFUME rising from its perfumer's bar to its HOUSE; every house
   a node of squares — the first as big as its perfumes, then one for each
   of its perfumers, in their colours — its name over them, standing AT THE
   HEIGHT OF ITS PERFUMES' YEARS (the middle year of them, the years ruled
   down the left and rising, the newest highest; "year not found" along the
   top), and across where its perfumers stand. Lights run up the threads.
   Pointed at, a perfumer's, a house's or one perfume's threads light;
   pressed, its panel opens on the right — a perfumer's or a house's
   perfumes, each pressed lighting its own thread. The search finds any of
   them; the switch above the perfumers puts the threads by year instead.

   A snapshot of the site's Perfumers ledger, written in above: nothing on
   the site reads this page, and it reads nothing of the site.
   ============================================================ */
(function () {
  "use strict";
  const STILL = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  const TAU = Math.PI * 2;
  const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
  const lerp = (a, b, t) => a + (b - a) * t;
  const ease = (t) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);
  function rng(seed) { let s = seed >>> 0; return () => ((s = (s * 1664525 + 1013904223) >>> 0) / 4294967296); }
  const cmp = (a, b) => String(a).localeCompare(String(b), "en", { sensitivity: "base" });
  const fold = (t) => String(t).normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase();
  const el = (s) => document.querySelector(s);

  // ---- THE DATA ---------------------------------------------------------
  const D = DATA;
  const CREDIT = ["named by a source", "the house's perfumer", "perfumer not found"];
  const KIND = ["an individual fragrance written about here", "a house perfume written about here", "Prin Lomros' houses, not written about here"];
  const PER = D.perfumers.map((p, i) => Object.assign({}, p, { i, list: [], none: p.id === "not-found" }));
  const HOU = D.houses.map((h, i) => Object.assign({}, h, { i, list: [], by: new Map() }));
  const ENT = [];
  D.perfumes.forEach((r) => r[1].forEach((q) => {
    const e = { n: r[0], q, c: r[2], y: r[3], h: r[4], k: r[5], s: r[6], who: r[1] };
    ENT.push(e); PER[q].list.push(e); HOU[r[4]].list.push(e);
    HOU[r[4]].by.set(q, (HOU[r[4]].by.get(q) || 0) + 1);
  }));
  const ORDER = PER.slice().sort((a, b) => (a.none - b.none) || cmp(a.sort, b.sort));
  ORDER.forEach((p, k) => (p.k = k));
  // the poster's colours, red at the left through orange and gold to white
  const STOPS = [[214, 72, 66], [228, 112, 82], [240, 162, 98], [242, 204, 128], [240, 230, 196], [236, 234, 228]];
  function colourAt(t) {
    const x = clamp(t, 0, 1) * (STOPS.length - 1), i = Math.min(STOPS.length - 2, Math.floor(x)), u = x - i;
    return STOPS[i].map((v, j) => Math.round(lerp(v, STOPS[i + 1][j], u)));
  }
  ORDER.forEach((p) => { p.rgb = colourAt(ORDER.length > 1 ? p.k / (ORDER.length - 1) : 0); p.css = "rgb(" + p.rgb.join(",") + ")"; });
  const Y0 = 2009, Y1 = 2026;
  HOU.forEach((h) => {
    const ys = h.list.map((e) => e.y).filter(Boolean).sort((a, b) => a - b);
    h.year = ys.length ? ys[Math.floor((ys.length - 1) / 2)] : 0;
    h.ys = ys;
  });

  // ---- THE PAGE ------------------------------------------------------------
  const cv = el(".t3-scene"), ctx = cv.getContext("2d");
  const tip = el(".t3-tip"), panel = el(".t3-panel");
  let W = 0, H = 0, DPR = 1, phone = false;
  const L = { x0: 0, x1: 0, barY: 0, top: 0, bottom: 0, unit: 1, labelH: 0 };
  let mode = "az";

  function layout() {
    W = window.innerWidth;
    phone = W < 760;
    // a tall poster, as the picture's: a little taller than the window
    H = Math.max(window.innerHeight + (phone ? 560 : 140), phone ? 1480 : 1000);
    DPR = Math.min(window.devicePixelRatio || 1, 2);
    cv.width = Math.round(W * DPR); cv.height = Math.round(H * DPR);
    cv.style.width = W + "px"; cv.style.height = H + "px";
    el(".t3").style.height = H + "px";
    const head = el(".t3-head").getBoundingClientRect(), tools = el(".t3-tools").getBoundingClientRect();
    L.x0 = phone ? 18 : Math.max(96, W * 0.07);
    L.x1 = W - (phone ? 18 : Math.max(60, W * 0.05));
    L.labelH = phone ? 92 : 132;
    // the houses under the head (and on a phone the search, which stands
    // under it), room left over each for its name
    const under = Math.max(head.bottom, tools.bottom) + window.scrollY;
    L.top = under + (phone ? 64 : 74);
    // the perfumers' bars along the foot, their names under them, clear of
    // the legend
    const legendTop = H - el(".t3-legend").offsetHeight - (phone ? 22 : 34);
    L.barY = legendTop - L.labelH - (phone ? 30 : 40);
    L.bottom = L.barY - (phone ? 60 : 90);
    // the perfumers' bars: as wide as their perfumes, each slot wide enough
    // for its name upright over it
    const minSlot = phone ? 11 : 13.5, gap = phone ? 3 : 5;
    const span = L.x1 - L.x0;
    let unit = (span - gap * (ORDER.length - 1)) / ENT.length;
    for (let it = 0; it < 30; it++) {
      let used = 0, small = 0, smallW = 0;
      ORDER.forEach((p) => { const w = p.list.length * unit; if (w < minSlot) { small++; smallW += minSlot; } else used += p.list.length; });
      unit = (span - gap * (ORDER.length - 1) - smallW) / Math.max(1, used);
    }
    L.unit = unit;
    let x = L.x0;
    ORDER.forEach((p) => {
      const w = p.list.length * unit, slot = Math.max(minSlot, w);
      p.x0 = x + (slot - w) / 2; p.x1 = p.x0 + w; p.cx = x + slot / 2; p.slot0 = x; p.slot1 = x + slot;
      x += slot + gap;
    });
    layHouses();
    layThreads();
  }
  // where the houses stand: as high as their perfumes' middle year, across
  // where their perfumers' bars are — and pushed apart so none covers
  // another's name
  function yOf(year) { return year ? lerp(L.bottom, L.top + (phone ? 60 : 80), (year - Y0) / (Y1 - Y0)) : L.top; }
  function layHouses() {
    HOU.forEach((h) => {
      let sx = 0, n = 0;
      h.list.forEach((e) => { const p = PER[e.q]; sx += p.cx; n++; });
      h.tx = n ? sx / n : W / 2;
      h.ty = yOf(h.year);
      h.x = h.tx; h.y = h.ty;
      h.w = labelW(h) + 18; h.hh = phone ? 52 : 66;
    });
    const R = rng(7);
    for (let it = 0; it < 220; it++) {
      for (let i = 0; i < HOU.length; i++) for (let j = i + 1; j < HOU.length; j++) {
        const a = HOU[i], b = HOU[j];
        const ox = (a.w + b.w) / 2 - Math.abs(a.x - b.x), oy = (a.hh + b.hh) / 2 - Math.abs(a.y - b.y);
        if (ox > 0 && oy > 0) {
          if (ox < oy * (phone ? 0.7 : 1.6)) { const s = (a.x < b.x || (a.x === b.x && R() < 0.5) ? -1 : 1) * ox / 2; a.x += s; b.x -= s; }
          else { const s = (a.y < b.y ? -1 : 1) * oy / 2; a.y += s; b.y -= s; }
        }
      }
      HOU.forEach((h) => { h.x += (h.tx - h.x) * 0.02; h.y += (h.ty - h.y) * 0.04; h.x = clamp(h.x, L.x0 + h.w / 2, L.x1 - h.w / 2); h.y = clamp(h.y, L.top, L.bottom); });
    }
  }
  function labelW(h) {
    ctx.font = "700 " + (phone ? 9.5 : 11) + "px Archivo, sans-serif";
    return Math.max(ctx.measureText(h.name).width, squaresW(h));
  }
  // a house's squares: the first as big as its perfumes, then one for each
  // of its perfumers, as big as what that perfumer made for it
  const sq = (n) => (phone ? 3 : 4) + Math.sqrt(n) * (phone ? 1.6 : 2.2);
  function squaresW(h) { let w = sq(h.list.length) + 6; h.by.forEach((n) => (w += sq(n) * 0.62 + 3)); return w; }
  // the threads: one for every perfume, from its place in its perfumer's bar
  // to its house, falling in a curve — in its perfumer's colour
  let threads = [];
  function layThreads() {
    threads = [];
    ORDER.forEach((p) => {
      // its perfumes along its bar, by where their houses stand
      const list = p.list.slice().sort((a, b) => (mode === "year" ? (a.y || 9999) - (b.y || 9999) : 0) || HOU[a.h].x - HOU[b.h].x || cmp(a.n, b.n));
      list.forEach((e, j) => {
        const h = HOU[e.h];
        const sx = p.x0 + (j + 0.5) * L.unit;
        // where it comes into its house: spread across the house's top, by perfumer
        const keys = Array.from(h.by.keys()).sort((a, b) => PER[a].k - PER[b].k);
        const slot = keys.indexOf(e.q), share = h.by.get(e.q);
        const k = h.list.filter((x) => x.q === e.q).indexOf(e);
        const width = Math.min(h.w - 10, 10 + h.list.length * (phone ? 0.7 : 1.1));
        let before = 0;
        keys.forEach((q, i) => { if (i < slot) before += h.by.get(q); });
        const ex = h.x - width / 2 + ((before + k + 0.5) / h.list.length) * width;
        const ey = h.y + sq(h.list.length) / 2 - 1;
        threads.push({ e, p, h, sx, sy: L.barY + 2, ex, ey, ph: (j * 0.137 + p.k * 0.31) % 1 });
      });
    });
  }

  // ---- WHAT IS LIT ----------------------------------------------------------
  let hover = null, chosen = null;            // { kind: "per"|"house"|"perfume", ... }
  const litOf = (t, s) => !s ? true : s.kind === "per" ? t.p === s.p : s.kind === "house" ? t.h === s.h : t.e === s.e;
  function curve(t, u) {
    const my = lerp(t.sy, t.ey, 0.5);
    // a cubic up from the bar and into the house
    const a = 1 - u;
    const x = a * a * a * t.sx + 3 * a * a * u * t.sx + 3 * a * u * u * t.ex + u * u * u * t.ex;
    const y = a * a * a * t.sy + 3 * a * a * u * my + 3 * a * u * u * my + u * u * u * t.ey;
    return [x, y];
  }

  // ---- DRAWING ------------------------------------------------------------
  let intro = STILL ? 1 : 0, introT0 = -1;
  const INTRO_MS = 2200;
  const lights = [];
  let lightNext = 0;
  function draw(now, t) {
    const c = ctx;
    c.setTransform(DPR, 0, 0, DPR, 0, 0);
    c.fillStyle = "#262628"; c.fillRect(0, 0, W, H);
    const sel = hover || chosen;
    // the years down the left
    c.font = "400 " + (phone ? 8.5 : 9.5) + 'px "IBM Plex Mono", monospace';
    c.fillStyle = "rgba(236,234,228,0.32)";
    // on a phone there is no margin to name the years in: over their rules
    const yx = phone ? L.x0 : L.x0 - 8, yd = phone ? -6 : 0;
    c.textAlign = phone ? "left" : "right"; c.textBaseline = "middle";
    c.strokeStyle = "rgba(236,234,228,0.06)"; c.lineWidth = 1;
    for (let y = Y0; y <= Y1; y++) {
      if (y % (phone ? 4 : 2)) continue;
      const yy = yOf(y);
      c.beginPath(); c.moveTo(L.x0, yy); c.lineTo(L.x1, yy); c.stroke();
      c.fillText(String(y), yx, yy + yd);
    }
    c.fillText("year not found", yx, yOf(0) + yd);
    c.setLineDash([2, 4]); c.beginPath(); c.moveTo(L.x0, yOf(0)); c.lineTo(L.x1, yOf(0)); c.stroke(); c.setLineDash([]);
    // the threads, each drawn up as the page opens; what is lit drawn last
    const lit = [], rest = [];
    threads.forEach((th) => (litOf(th, sel) ? lit : rest).push(th));
    c.lineWidth = phone ? 0.8 : 1.1;
    const drawT = (th, alpha) => {
      const g = STILL ? 1 : ease(clamp(intro * 1.7 - th.ph * 0.7, 0, 1));
      if (g <= 0) return;
      c.strokeStyle = th.p.css; c.globalAlpha = alpha;
      c.beginPath();
      const n = 22;
      for (let i = 0; i <= n * g; i++) { const [x, y] = curve(th, i / n); if (!i) c.moveTo(x, y); else c.lineTo(x, y); }
      c.stroke();
    };
    rest.forEach((th) => drawT(th, sel ? 0.06 : 0.3));
    lit.forEach((th) => drawT(th, sel ? 0.85 : 0.3));
    c.globalAlpha = 1;
    // lights running up the threads
    if (!STILL && intro >= 1) {
      if (t > lightNext && lights.length < 24) { const pool = sel ? lit : threads; const th = pool[Math.floor(Math.random() * pool.length)]; if (th) lights.push({ th, t0: t, dur: 2.2 + Math.random() * 1.6 }); lightNext = t + 0.08 + Math.random() * 0.16; }
      for (let i = lights.length - 1; i >= 0; i--) {
        const l = lights[i], u = (t - l.t0) / l.dur;
        if (u >= 1) { lights.splice(i, 1); continue; }
        const [x, y] = curve(l.th, ease(u));
        c.globalAlpha = Math.sin(Math.PI * u) * (litOf(l.th, sel) ? 0.95 : 0.25);
        c.fillStyle = "#fff8ec";
        c.beginPath(); c.arc(x, y, phone ? 1.3 : 1.7, 0, TAU); c.fill();
      }
      c.globalAlpha = 1;
    }
    // the perfumers' bars and their names, upright under them
    const fs = phone ? 8.5 : 10;
    c.font = "500 " + fs + "px Archivo, sans-serif";
    ORDER.forEach((p) => {
      const on = !sel || (sel.kind === "per" ? sel.p === p : sel.kind === "house" ? sel.h.by.has(p.i) : sel.e.who.includes(p.i));
      c.globalAlpha = on ? 1 : 0.28;
      c.fillStyle = p.css;
      c.fillRect(p.x0, L.barY, Math.max(1.5, p.x1 - p.x0), phone ? 9 : 12);
      c.save();
      c.translate(p.cx + fs * 0.36, L.barY + (phone ? 9 : 12) + 8);
      c.rotate(-Math.PI / 2);
      c.textAlign = "right"; c.textBaseline = "alphabetic";
      c.fillStyle = on ? "#f4f2ec" : "rgba(244,242,236,0.5)";
      const name = p.none ? "Perfumer not found" : p.name;
      c.fillText(name.length > (phone ? 16 : 22) ? name.slice(0, phone ? 15 : 21) + "…" : name, 0, 0);
      c.restore();
    });
    c.globalAlpha = 1;
    // the houses: their squares, their names over them
    HOU.forEach((h) => {
      if (!h.list.length) return;
      const on = !sel || (sel.kind === "per" ? h.by.has(sel.p.i) : sel.kind === "house" ? sel.h === h : sel.e.h === h.i);
      const a = (STILL ? 1 : clamp(intro * 2 - 0.6, 0, 1)) * (on ? 1 : 0.3);
      if (a <= 0) return;
      c.globalAlpha = a;
      const big = sq(h.list.length);
      let x = h.x - squaresW(h) / 2;
      const y = h.y - big / 2;
      c.fillStyle = "#eceae4";
      c.fillRect(x, y, big, big);
      x += big + 6;
      Array.from(h.by.keys()).sort((a2, b2) => PER[a2].k - PER[b2].k).forEach((q) => {
        const s = sq(h.by.get(q)) * 0.62;
        c.fillStyle = PER[q].css;
        c.fillRect(x, y + big - s, s, s);
        x += s + 3;
      });
      c.font = "700 " + (phone ? 9.5 : 11) + "px Archivo, sans-serif";
      // a little of the ground behind its name, so the threads rising past
      // it never cross the letters
      const nw = c.measureText(h.name).width + 8;
      c.globalAlpha = a * 0.82;
      c.fillStyle = "#262628";
      c.fillRect(h.x - nw / 2, y - (phone ? 29 : 34), nw, phone ? 26 : 30);
      c.globalAlpha = a;
      c.fillStyle = "#f4f2ec"; c.textAlign = "center"; c.textBaseline = "bottom";
      c.fillText(h.name, h.x, y - (phone ? 16 : 19));
      c.font = "400 " + (phone ? 8 : 9) + 'px "IBM Plex Mono", monospace';
      c.fillStyle = "rgba(244,242,236,0.5)";
      c.fillText(h.list.length + (h.year ? " · " + h.year : ""), h.x, y - 5);
    });
    c.globalAlpha = 1;
    // the one perfume pointed at: its thread bright, a ring at each end
    if (sel && sel.kind === "perfume") {
      const th = threads.find((x) => x.e === sel.e);
      if (th) {
        c.strokeStyle = "#fff"; c.lineWidth = 2;
        c.beginPath();
        for (let i = 0; i <= 30; i++) { const [x, y] = curve(th, i / 30); if (!i) c.moveTo(x, y); else c.lineTo(x, y); }
        c.stroke();
        c.lineWidth = 1;
        for (const [x, y] of [[th.sx, th.sy], [th.ex, th.ey]]) { c.beginPath(); c.arc(x, y, 5, 0, TAU); c.stroke(); }
      }
    }
  }

  // ---- THE HAND ----------------------------------------------------------
  function at(x, y) {
    // a perfumer's bar or name
    if (y > L.barY - 10 && y < L.barY + L.labelH + 26) {
      const p = ORDER.find((q) => x >= q.slot0 - 1 && x <= q.slot1 + 1);
      if (p) return { kind: "per", p };
    }
    // a house
    for (const h of HOU) if (Math.abs(x - h.x) < h.w / 2 && Math.abs(y - (h.y - (phone ? 12 : 16))) < h.hh / 2 + 6) return { kind: "house", h };
    // a thread
    if (y < L.barY - 4) {
      let best = null, bd = phone ? 9 : 6;
      for (const th of threads) {
        if (y < Math.min(th.sy, th.ey) - 4 || y > Math.max(th.sy, th.ey) + 4) continue;
        for (let i = 0; i <= 24; i++) { const [px, py] = curve(th, i / 24); const d = Math.hypot(px - x, py - y); if (d < bd) { bd = d; best = th; } }
      }
      if (best) return { kind: "perfume", e: best.e, th: best };
    }
    return null;
  }
  const same = (a, b) => (!a && !b) || (a && b && a.kind === b.kind && (a.p || a.h || a.e) === (b.p || b.h || b.e));
  function tipFor(s) {
    if (s.kind === "per") {
      const p = s.p, hs = new Set(p.list.map((e) => e.h));
      return "<b>" + esc(p.none ? "Perfumer not found" : p.name) + "</b><span>" + p.list.length + " perfumes · " + hs.size + (hs.size === 1 ? " house" : " houses") + (p.from ? " · " + esc(p.from) : "") + "</span>";
    }
    if (s.kind === "house") {
      const h = s.h;
      return "<b>" + esc(h.name) + "</b><span>" + h.list.length + " perfumes · " + h.by.size + (h.by.size === 1 ? " perfumer" : " perfumers") + (h.year ? " · middle year " + h.year : "") + "</span>";
    }
    const e = s.e;
    return "<b>" + esc(e.n) + "</b><span>" + esc(HOU[e.h].name) + " · " + (e.y || "year not found") + "</span><span>" + esc(e.who.map((q) => (PER[q].none ? "perfumer not found" : PER[q].name)).join(" & ")) + "</span>";
  }
  function placeTip(x, y) {
    const tw = tip.offsetWidth, th = tip.offsetHeight;
    let px = x + 14, py = y + 14;
    if (px + tw > W - 10) px = x - tw - 14;
    if (py + th > window.scrollY + window.innerHeight - 10) py = y - th - 14;
    tip.style.transform = "translate(" + Math.round(Math.max(8, px)) + "px," + Math.round(Math.max(8, py)) + "px)";
  }
  cv.addEventListener("pointermove", (ev) => {
    if (ev.pointerType === "touch") return;
    const r = cv.getBoundingClientRect(), x = ev.clientX - r.left, y = ev.clientY - r.top;
    const s = at(x, y);
    if (!same(s, hover)) { hover = s; kick(); }
    if (s) { tip.innerHTML = tipFor(s); tip.hidden = false; placeTip(x, y); } else tip.hidden = true;
    cv.style.cursor = s ? "pointer" : "default";
  });
  cv.addEventListener("pointerleave", () => { hover = null; tip.hidden = true; kick(); });
  cv.addEventListener("click", (ev) => {
    const r = cv.getBoundingClientRect();
    const s = at(ev.clientX - r.left, ev.clientY - r.top);
    choose(s);
  });

  // ---- THE PANEL: what is chosen, and its perfumes --------------------------
  function choose(s) {
    chosen = s;
    hover = null; tip.hidden = true;
    if (!s) { panel.classList.remove("is-open"); panel.setAttribute("aria-hidden", "true"); kick(); return; }
    const list = s.kind === "per" ? s.p.list : s.kind === "house" ? s.h.list : [s.e];
    let h = "";
    if (s.kind === "per") {
      const p = s.p;
      h += '<p class="t3-k">Perfumer</p><h2>' + esc(p.none ? "Perfumer not found" : p.name) + "</h2>";
      h += '<p class="t3-m">' + [p.from, p.born ? "born " + p.born : ""].filter(Boolean).map(esc).join(" · ") + "</p>";
      if (p.about.length) h += "<p class=\"t3-a\">" + esc(p.about.slice(0, 2).join(" ")) + "</p>";
    } else if (s.kind === "house") {
      const ho = s.h;
      h += '<p class="t3-k">House</p><h2>' + esc(ho.name) + "</h2>";
      h += '<p class="t3-m">' + [ho.from, ho.founded ? "founded " + ho.founded : "", ho.site ? "written about here" : ""].filter(Boolean).map(esc).join(" · ") + "</p>";
      if (ho.about) h += '<p class="t3-a">' + esc(ho.about) + "</p>";
      h += '<p class="t3-m">By ' + Array.from(ho.by.entries()).sort((a, b) => b[1] - a[1]).map(([q, n]) => '<button type="button" data-per="' + q + '" style="color:' + PER[q].css + '">' + esc(PER[q].none ? "not found" : PER[q].name) + "</button> " + n).join(", ") + "</p>";
    } else {
      const e = s.e;
      h += '<p class="t3-k">Perfume</p><h2>' + esc(e.n) + "</h2>";
      h += '<dl class="t3-facts"><dt>Perfumer</dt><dd>' + e.who.map((q) => '<button type="button" data-per="' + q + '">' + esc(PER[q].none ? "not found" : PER[q].name) + "</button>").join(" & ") + " — " + CREDIT[e.c] + "</dd>" +
        '<dt>House</dt><dd><button type="button" data-house="' + e.h + '">' + esc(HOU[e.h].name) + "</button></dd><dt>Year</dt><dd>" + (e.y || "not found") + "</dd><dt>What it is</dt><dd>" + esc(KIND[e.k]) + "</dd>" +
        "<dt>Sources</dt><dd>" + (e.s.length ? e.s.map((i) => esc(D.sources[i])).join(", ") : "—") + "</dd></dl>";
    }
    if (s.kind !== "perfume") {
      const rows = list.slice().sort((a, b) => (a.y || 9999) - (b.y || 9999) || cmp(a.n, b.n));
      h += '<h3>' + rows.length + (rows.length === 1 ? " perfume" : " perfumes") + "</h3><ol class=\"t3-list\">" + rows.map((e) =>
        '<li><button type="button" data-entry="' + ENT.indexOf(e) + '"><span>' + esc(e.n) + "</span><i>" + esc(s.kind === "per" ? HOU[e.h].name : PER[e.q].none ? "not found" : PER[e.q].name) + "</i><b>" + (e.y || "—") + "</b></button></li>").join("") + "</ol>";
    }
    el(".t3-panel-body").innerHTML = h;
    panel.classList.add("is-open");
    panel.setAttribute("aria-hidden", "false");
    el(".t3-panel-body").scrollTop = 0;
    kick();
  }
  panel.addEventListener("click", (ev) => {
    if (ev.target.closest(".t3-close")) { choose(null); return; }
    const p = ev.target.closest("[data-per]"); if (p) { choose({ kind: "per", p: PER[+p.dataset.per] }); return; }
    const ho = ev.target.closest("[data-house]"); if (ho) { choose({ kind: "house", h: HOU[+ho.dataset.house] }); return; }
    const en = ev.target.closest("[data-entry]"); if (en) { const e = ENT[+en.dataset.entry]; hover = { kind: "perfume", e }; kick(); }
  });
  panel.addEventListener("pointerover", (ev) => {
    const en = ev.target.closest("[data-entry]");
    if (en) { hover = { kind: "perfume", e: ENT[+en.dataset.entry] }; kick(); }
  });
  panel.addEventListener("pointerleave", () => { if (hover) { hover = null; kick(); } });
  document.addEventListener("keydown", (ev) => { if (ev.key === "Escape") { if (find.value) { find.value = ""; found(); } else choose(null); } });

  // ---- THE SEARCH -----------------------------------------------------------
  const find = el(".t3-find input"), hits = el(".t3-hits");
  const all = [];
  ORDER.forEach((p) => all.push({ kind: "per", p, name: p.none ? "Perfumer not found" : p.name, say: "Perfumer · " + p.list.length }));
  HOU.forEach((h) => { if (h.list.length) all.push({ kind: "house", h, name: h.name, say: "House · " + h.list.length }); });
  ENT.forEach((e) => all.push({ kind: "perfume", e, name: e.n, say: HOU[e.h].name + " · " + (e.y || "—") }));
  all.forEach((a) => (a.key = fold(a.name)));
  let hitList = [];
  function found() {
    const q = fold(find.value.trim());
    if (!q) { hits.hidden = true; hits.innerHTML = ""; hitList = []; return; }
    hitList = all.filter((a) => a.key.includes(q)).sort((a, b) => (a.key.indexOf(q) ? 1 : 0) - (b.key.indexOf(q) ? 1 : 0) || cmp(a.name, b.name)).slice(0, 12);
    hits.innerHTML = hitList.length ? hitList.map((a, i) => '<li><button type="button" data-hit="' + i + '">' + esc(a.name) + "<small>" + esc(a.say) + "</small></button></li>").join("") : "<li class=\"t3-none\">Nothing by that name</li>";
    hits.hidden = false;
  }
  find.addEventListener("input", found);
  find.addEventListener("keydown", (ev) => { if (ev.key === "Enter" && hitList[0]) { ev.preventDefault(); take(hitList[0]); } });
  hits.addEventListener("click", (ev) => { const b = ev.target.closest("[data-hit]"); if (b) take(hitList[+b.dataset.hit]); });
  function take(a) { find.value = ""; found(); choose(a.kind === "per" ? { kind: "per", p: a.p } : a.kind === "house" ? { kind: "house", h: a.h } : { kind: "perfume", e: a.e }); }

  // ---- THE SWITCH: the threads along each bar by house, or by year ----------
  document.querySelectorAll(".t3-sort button").forEach((b) => b.addEventListener("click", () => {
    mode = b.dataset.sort;
    document.querySelectorAll(".t3-sort button").forEach((x) => x.setAttribute("aria-pressed", x === b ? "true" : "false"));
    layThreads(); kick();
  }));

  // ---- THE CLOCK -------------------------------------------------------------
  let raf = 0, last = 0, clock = 0;
  function frame(now) {
    raf = 0;
    const dt = last ? Math.min(0.05, (now - last) / 1000) : 1 / 60;
    last = now;
    if (!STILL) clock += dt;
    if (introT0 < 0) introT0 = now;
    if (!STILL) intro = clamp((now - introT0) / INTRO_MS, 0, 1);
    draw(now, clock);
    if (!STILL && !document.hidden) raf = requestAnimationFrame(frame);
    else last = 0;
  }
  function kick() { if (!raf) raf = requestAnimationFrame(frame); }
  document.addEventListener("visibilitychange", () => { if (!document.hidden) { last = 0; kick(); } });
  let rq = 0;
  window.addEventListener("resize", () => { if (rq) return; rq = requestAnimationFrame(() => { rq = 0; layout(); kick(); }); });
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(() => { layout(); kick(); });
  layout();
  kick();
  window.TestPage3 = {
    threads: () => threads.length,
    perfumers: ORDER.length,
    houses: HOU.filter((h) => h.list.length).length,
    choose: (kind, id) => {
      if (kind === "per") choose({ kind, p: PER.find((p) => p.id === id) });
      else if (kind === "house") choose({ kind, h: HOU.find((h) => h.id === id) });
      else choose(null);
    },
    chosen: () => (chosen ? { kind: chosen.kind, id: chosen.p ? chosen.p.id : chosen.h ? chosen.h.id : chosen.e.n } : null),
    houseAt: (id) => { const h = HOU.find((x) => x.id === id); const r = cv.getBoundingClientRect(); return h ? { x: r.left + h.x, y: r.top + h.y } : null; },
    perfumerAt: (id) => { const p = PER.find((x) => x.id === id); const r = cv.getBoundingClientRect(); return p ? { x: r.left + p.cx, y: r.top + L.barY + 4 } : null; },
    yearOf: (id) => { const h = HOU.find((x) => x.id === id); return h ? h.year : null; },
    yOfHouse: (id) => { const h = HOU.find((x) => x.id === id); return h ? h.y : null; },
  };
})();
